import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    orders_info = {}
    seq_counter = 0
    trades = []

    def add_to_book(oid):
        info = orders_info[oid]
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], info['seq'], oid))
        else:
            heapq.heappush(sell_heap, (info['price'], info['seq'], oid))

    def match_incoming(oid, side, price, qty, is_market):
        remaining = qty
        heap = sell_heap if side == 'buy' else buy_heap
        while remaining > 0 and heap:
            top = heap[0]
            resting_id = top[2]
            info = orders_info.get(resting_id)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            resting_price = info['price']
            if not is_market:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break
            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                trades.append([oid, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, oid, resting_price, trade_qty])
            remaining -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(heap)
            # if info['qty'] > 0, then remaining must be 0, loop will end naturally
        return remaining

    for order in orders:
        seq_counter += 1
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            orders_info[oid] = {'side': side, 'price': price, 'qty': qty,
                                 'seq': seq_counter, 'active': True}
            remaining = match_incoming(oid, side, price, qty, False)
            orders_info[oid]['qty'] = remaining
            if remaining > 0:
                add_to_book(oid)
            else:
                orders_info[oid]['active'] = False

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            orders_info[oid] = {'side': side, 'price': price, 'qty': qty,
                                 'seq': seq_counter, 'active': True}
            remaining = match_incoming(oid, side, price, qty, False)
            orders_info[oid]['qty'] = remaining
            orders_info[oid]['active'] = False  # discard remainder, never rests

        elif typ == 'market':
            _, oid, side, qty = order
            orders_info[oid] = {'side': side, 'price': None, 'qty': qty,
                                 'seq': seq_counter, 'active': True}
            remaining = match_incoming(oid, side, None, qty, True)
            orders_info[oid]['qty'] = remaining
            orders_info[oid]['active'] = False  # discard remainder, never rests

    return trades

